custom_css:
/* 作者：lazyalie */
/* 作者有话说:禁二传商用。感谢帮助过我的老师们 */
/* 部分代码来自教程帖以及尾巴老师的拼好码，教程帖指路https://discord.com/channels/1291925535324110879/1380392618336194702;拼好码指路https://discord.com/channels/1291925535324110879/1422717884378910801 */
/* 二改：海风、-肉桂苹果糖 */
/* 头图素材来自小红书:薄荷猫^ ^ */
/* 调色参照小红书:今日特调色 */
/* 文案来自小红书:柚心动了✨/一小点点点..zm/54Jt */

@import url("https://fontsapi.zeoseven.com/309/main/result.css");/* "KingHwaOldSong" */
@import url("https://fontsapi.zeoseven.com/379/main/result.css");/* "TW-Sung" */

/* =====全局控制与肉桂苹果糖调色板===== */
:root {
  --全局字体: "KingHwaOldSong";
  --三元素字体: "TW-Sung";
  --头像大小: 38cqw;
  --头像上下: 35%;
  --头像左右: 20.5%;
  --头像显示区域: center 50%; /*改数字调整头像到你想看到的部位，感谢咩野老师的代码*/
  --模糊度: 6px;
  --气泡宽度: 100%;
  --气泡间距: 70px;
  --气泡与输入框间距: 50px;
  --输入框内文字: "在感受 在记录";

  /* --- 肉桂苹果糖色彩配置 --- */
  --candy-ultra-light: #FFFAEB; /* 温和的奶油糖衣白 */
  --candy-light: #D8ECEF;       /* 剔透冰蓝水色 */
  --candy-sky: #A0CBD2;         /* 灰蓝色的冷调倒影 */
  --candy-text-dark: #94102C;   /* 肉桂与苹果的深浸红 */
  --candy-text-light: #ffffff;  /* 纯白文字 */
  --candy-shadow: rgba(148, 16, 44, 0.15); /* 淡淡的暖红透光阴影 */
  --candy-bubble-bg: rgba(255, 250, 235, 0.7); /* 奶油霜背景半透 */
}
/* =====全局控制结束===== */

body {
    font-family: var(--全局字体);
    font-weight: normal;
}

/* =====补丁部分===== */
div.inline-drawer-content {
  z-index: 2147483647 !important;
  position: relative !important;
}

/*感谢咩野老师的全局阴影去除*/
body *:not(#send_form):not(#send_form *):not(.mes .avatar ):not(.mes .avatar *):not(.mes .mes_reasoning_header ):not(.completion_prompt_manager_prompt):not(textarea):not(blockquote){
  box-shadow: none !important;
  border: none!important;
  filter: none!important;
}

/* ========文本调节======== */
.mes .mes_text {
  letter-spacing: 1.8px;
  line-height: 1.5;
  text-align: justify !important;
  padding-left: 1px;
  padding-right: 1px;
}
p {
  text-indent: 0em;
}

/* =====全局抽屉===== */
body.no-blur .drawer-content.openDrawer{
  backdrop-filter: blur(var(--模糊度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊度)) !important;
}

/* ====顶栏==== */
#top-settings-holder .drawer-icon{
  color: var(--candy-text-dark) !important;
  -webkit-text-stroke: 3px var(--candy-light) !important;
  paint-order: stroke fill !important;
  font-size: 1.5em;
  opacity: 1;
}

/* ====底栏==== */
#send_form [class*="fa-"] {
  color: var(--candy-text-dark) !important;
  -webkit-text-stroke: 2px var(--candy-light) !important;
  paint-order: stroke fill !important;
  font-size: 0.8em;
}
/* 感谢nini老师分享的隐藏输入框小黑点 */
#send_textarea {
  resize: none !important;
}
/* 感谢墨千尾老师的输入框内文字自定义 */
#nonQRFormItems {
  position: relative;
}
#send_textarea::placeholder {
  color: rgba(0, 0, 0, 0) !important;
  text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--输入框内文字);
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  color: var(--candy-text-dark);
  font-style: normal;
  font-size: 0.5em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}

#send_textarea {
  background: var(--candy-ultra-light)!important;
  color: var(--candy-text-dark)!important;
  border-radius: 0 !important;
  padding: 2px;
  margin: 2px 1px;
  box-shadow: 2px 2px 8px var(--candy-shadow)!important;
}
/* 感谢nakari老师的悬浮底栏 */
#sheld,
#chat {
  height: calc(102dvh + var(--bottomFormBlockSize));
  max-height: calc(102dvh + var(--bottomFormBlockSize));
}

#send_form {
  backdrop-filter: blur(var(--模糊度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊度)) !important;
  border: 1px solid rgba(255, 255, 255, 0.45);
  width: 95%;
  display: flex !important;
  align-items: center !important;
  border-radius: 0px !important;
  padding: 8px 15px !important;
  box-shadow: 2px 2px 10px var(--candy-shadow);
  transition: all 0.3s ease;
  background: rgba(255, 250, 235, 0.4) !important;
}

#form_sheld {
  position: sticky;
  bottom: 90px;
  transition: transform 0.3s ease;
}

/* ====按钮图标类==== */
.menu_button,
.menu_button * {
  background: var(--candy-ultra-light)!important;
  color: var(--candy-text-dark)!important;
  border-radius: 0 !important;
  border: none!important;
  box-shadow: 2px 2px 6px var(--candy-shadow) !important;
  padding: 2px 5px !important;
}
.menu_button.redWarningBG,
.menu_button.red_button {
  color: #A0CBD2 !important;
}
.menu_button.world_set,
.menu_button.fav_on {
  color: #94102C !important;
}

/* ======复选框====== */
input[type="checkbox"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 16px !important;
  height: 16px !important;
  border-radius: 0 !important;
  border: none !important;
  background: var(--candy-ultra-light) !important;
  box-shadow: 2px 2px 5px var(--candy-shadow) !important;
  cursor: pointer !important;
}

input[type="checkbox"]:checked {
  background: var(--candy-sky) !important;
}
/*感谢nakari老师的防误触*/
/* 取消label交互 */
.checkbox_label {
  pointer-events: none !important;
}
/* 恢复复选框交互 */
input[type="checkbox"] {
  pointer-events: auto !important;
}

/* =====滚动条和滑动条===== */
::-webkit-scrollbar {
  display: none !important;
}
* {
  scrollbar-width: none !important;
}

/* ====角色和用户区域==== */
/* 收藏区左右滑动 - 感谢twelve老师 */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  height: calc(var(--avatar-base-height) + 10px);
}
body.big-avatars #HotSwapWrapper > div {
  height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
.character_select.is_fav,
.avatar-container.interactable.selected{
  background: var(--candy-ultra-light)!important;
  border-radius: 0 !important;
  color: var(--candy-text-dark)!important;
}
.character_select.is_fav .avatar  {
  margin: 0 !important;
  padding: 0 !important;
  outline: none !important;
}
.character_select.is_fav .ch_name {
  color: var(--candy-text-dark)!important;
}

/* =====预设部分===== */
ul#completion_prompt_manager_list.text_pole.ui-sortable {
  background: none!important;
}
.completion_prompt_manager_prompt {
  padding: 8px 42px !important;
}
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled),
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) * {
  background: var(--candy-ultra-light) !important;
  color: var(--candy-text-dark) !important;
  box-shadow: 2px 2px 6px var(--candy-shadow)!important;
  border: none!important;
}

/* =====七七八八框框===== */
.height100p.wide100p.maximized_textarea {
  background: transparent;
}
textarea:not(#send_textarea,.height100p.wide100p.maximized_textarea),
input[type="number"]{
  background: var(--candy-ultra-light)!important;
  color: var(--candy-text-dark)!important;
  border-radius: 0 !important;
  box-shadow: 2px 2px 5px var(--candy-shadow) !important;
  padding: 8px 15px !important;
  margin-bottom: 7px;
}
.popup[open]::backdrop{
  background: var(--candy-ultra-light);
}
.text_pole,
select{
  background: transparent;
  margin: 5px;
}
#user-settings-block h4,
.standoutHeader{
  background: var(--candy-ultra-light)!important;
  color: var(--candy-text-dark)!important;
  padding: 12px 24px;
}
.inline-drawer-header{
  background-image: none!important;
  background-color: none!important;
  padding: 12px 24px;
  margin: 12px 12px;
}
div.inline-drawer-content {
  background: transparent!important;
  border: none !important;
  background-image: none!important;
  background-color: none!important;
  padding: 8px;
  margin-top: 5px;
}
/* 感谢咩野老师：修改弹窗提示框背景颜色 */
.toast {
  background-color: var(--candy-light) !important;
  color: var(--candy-text-dark) !important;
}

body.no-blur div#extensionsMenu.options-content{
  backdrop-filter: blur(var(--模糊度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊度)) !important;
  font-family: var(--全局字体)!important;
}
div#options.font-family-reset {
  backdrop-filter: blur(var(--模糊度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊度)) !important;
  font-family: var(--全局字体)!important;
}

span.select2-selection,
span#select2-world_editor-container.select2-selection__rendered,
span#select2-world_info-container-choice-62yu-126.select2-selection__choice__display{
  background: var(--candy-ultra-light)!important;
  border-radius: 0 !important;
  color: var(--candy-text-dark)!important;
}

/* ===对话区域=== */
#chat{
  background: none!important;
  container-type: inline-size !important;
  container-name: chat !important;
  padding-bottom: var(--气泡与输入框间距);
}

.mes {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  border-radius: 0px!important;
  border: none!important;
  margin-bottom: var(--气泡间距)!important;
  background: transparent!important;
}

.mes .mesAvatarWrapper {
  width: 100% !important;
  order: 1 !important;
  margin-bottom: calc(var(--头像大小) * 0.76) !important;
  position: relative;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 1px !important;
}

.mes .mes_block {
  order: 2 !important;
  width: 100% !important;
  max-width: 100% !important;
  z-index: 1 !important;
}

.mes .avatar {
  width: var(--头像大小) !important;
  height: calc(var(--头像大小) * 1.1/1.6) !important;
  position: absolute;
  top: var(--头像上下);
  left: var(--头像左右);
  z-index: 22;
  filter: none !important;
  transform: none !important;
  box-shadow: none!important;
  border: none!important;
}

.mes .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  border-radius: inherit;
  object-position: var(--头像显示区域);
  box-shadow: 0 4px 12px var(--candy-shadow) !important;
  border: none!important;
  z-index: 25;
}

.mes .avatar::after {
  content: '';
  position: absolute;
  bottom: -28%;
  left: -27%;
  width: 257%;
  height: auto;
  aspect-ratio: 300/108;
  background-image: url('https://i.postimg.cc/K8Jv8sF5/retouch-2026031504374076.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  z-index: 20;
  pointer-events: none;
  transform: translateX(-10%);
}

/*感谢nakari老师分享的最后一条消息与下方区域距离保持一致代码*/
/* 通用CSS */
.mes .mes_timer:empty,
.mes .mesIDDisplay:empty,
.mes .tokenCounterDisplay:empty {
  display: none;
}
.last_mes .mesAvatarWrapper {
  padding-bottom: 0px;
}

.mes .mes_block {
  background: var(--candy-bubble-bg);
  backdrop-filter: blur(var(--模糊度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊度)) !important;
  border-radius: 0px !important;
  width: var(--气泡宽度) !important;
  max-width: none !important;
  padding: 15px !important;
  position: relative !important;
  margin-top: 0 !important;
  color: var(--candy-text-dark);
}

.mes .mesIDDisplay {
  color: var(--candy-text-light);
  opacity: 1;
  font-size: 6cqw;
  font-weight: bold !important;

  transform: translateY(-8px) !important;
  -webkit-text-stroke: 2px var(--candy-light) !important;
  paint-order: stroke fill !important;
}

.mes .mesIDDisplay::before { content: "第" !important; font-weight: normal !important; margin-right: 2px !important; }
.mes .mesIDDisplay::after { content: "章" !important; font-weight: normal !important; margin-left: 2px !important; }

.mes .mes_timer {
  font-size: 2cqw!important;
  position: relative !important;
  color: var(--candy-text-dark);
}
.mes .mes_timer::before { content: "还需" !important; font-weight: normal !important; margin-right: 2px !important; }

.mes .tokenCounterDisplay {
  font-size: 2cqw!important;
  position: relative !important;
  color: var(--candy-text-dark);
}
.mes .tokenCounterDisplay::before { content: "可解锁" !important; font-weight: normal !important; margin-right: 4px !important; }
.mes .tokenCounterDisplay::after { content: "章" !important; font-weight: normal !important; margin-left: 2px !important; }

.mes .mesIDDisplay {
  font-family: var(--三元素字体);
  position: absolute !important;
  top: calc(var(--头像大小) * 0.6) !important;
  left: calc(var(--头像大小) * 0.54) !important;
  z-index: 35 !important;
}
.mes .mes_timer,
.mes .tokenCounterDisplay {
  font-family: var(--三元素字体);
  position: relative !important;
  top: calc(var(--头像大小) * 0.63) !important;
  left: calc(var(--头像大小) * 1.67) !important;
  z-index: 35 !important;
}

#chat .mes .mes_block .flex-container.alignItemsBaseline{
  position: absolute !important;
  bottom: -55px;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  background: var(--candy-bubble-bg) !important;
  border-radius: 0 !important;
  padding: 15px 15px !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 8px !important;
  z-index: 5 !important;
}

.mes .flex-container.alignItemsBaseline::before,
.mes .flex-container.alignItemsBaseline::after {
  content: "" !important;
  flex: 1 !important;
  height: 1px !important;
  background: var(--candy-light) !important;
  min-width: 10px !important;
}

.mes .mes_block {
  position: relative !important;
  margin-bottom: 90px !important;
  overflow: visible !important;
}

.mes .flex-container.alignItemsBaseline .ch_name::before,
.mes .flex-container.alignItemsBaseline .name_text::before {
  content: "◉ 我说:" !important;
  font-size: 0.9em !important;
  margin-right: 2px !important;
  color: var(--candy-text-dark);
}
.ch_name{
  font-size: 0.9em !important;
  font-weight: 400;
  color: var(--candy-text-dark);
}
.mes .timestamp::before { content: "此刻最好:" !important; margin-right: 2px !important; color: var(--candy-text-dark); }
.mes .timestamp::after { content: " ◉" !important; margin-right: 2px !important; color: var(--candy-text-dark); }
.mes .timestamp{
  opacity: 1;
  font-size: 0.9em !important;
  color: var(--candy-text-dark);
}

/* 左切换箭头 */
.swipe_left {
  left: auto;
  bottom: 5px;
  left: 10px;
  background: var(--candy-bubble-bg) !important;
  border-radius: 0 !important;
  font-size: 0 !important;
  opacity: 1;
  display: block !important;
  width: 39px !important;
  height: 26px !important;
}

/* 消息数 */
.swipes-counter {
  transform: translateX(-450%) translateY(40%);
  z-index: 50;
  font-size: 0.8em;
  color: var(--candy-text-dark);
  opacity: 1;
}
/* 右切换箭头 */
.swipeRightBlock {
  margin-right: 5px;
  margin-bottom: 12px;
}
.swipe_right {
  position: absolute;
  background: var(--candy-bubble-bg) !important;
  border-radius: 0 !important;
  font-size: 0 !important;
  opacity: 1!important;
  display: block !important;
  width: 39px !important;
  height: 26px !important;
}
.swipe_left::after {
  content: "←";
  color: var(--candy-text-dark);
  position: absolute;
  bottom: 7px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 14px;
  font-weight: bold;
  white-space: nowrap;
}
.swipe_right::after {
  content: "→";
  color: var(--candy-text-dark);
  position: absolute;
  bottom: 7px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 14px;
  font-weight: bold;
  white-space: nowrap;
}

/* =====思维链===== */
.mes .mes_reasoning_header {
  background: rgba(255, 255, 255, 0.8) !important;
  color: var(--candy-text-dark);
  border-radius: 0 !important;
  box-shadow: 2px 2px 8px var(--candy-shadow) !important;
  padding: 8px 15px !important;
  transform: translateY(-25px) !important;
}
.mes .mes_reasoning_arrow {
  display: none !important;
}
.mes .mes_reasoning_header_title {
  font-size: 0 !important;
}
.mes .mes_reasoning_header_title::after {
  content: "：未拆封的時差禮物。" !important;
  font-size: 14px !important;
}

.mes .mes_reasoning {
  background: #ffffff !important;
  max-height: 200px !important;
  overflow-y: auto !important;
  border-left: none !important;
  color: var(--candy-text-dark);
}

.mes .mes_reasoning::-webkit-scrollbar { display: none !important; }
.mes .mes_reasoning::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.4) !important;
  border-radius: 2px !important;
}
.mes .mes_reasoning::-webkit-scrollbar-track { background: transparent !important; }

/* 文本美化 */
q{
  font-weight: 600;
  color: var(--candy-light);
}
pre code,
code:not(pre code.hljs){
  background: var(--candy-light) !important;
  color: var(--candy-text-dark)!important;
  border-radius: 0 !important;
}
blockquote{
  background: var(--candy-light) !important;
  color: var(--candy-text-dark) !important;
  box-shadow: 2px 2px 6px var(--candy-shadow) !important;
  border-left: 4px solid var(--candy-text-dark) !important;
}

/* ===== 选中文字的背景颜色设置 ===== */
::selection {
  background-color: var(--candy-sky) !important;
}

::-moz-selection {
  background-color: var(--candy-sky) !important;
}
